    sessions = conv.get('conversation', [])
    for session in sessions:
        for turn in session if isinstance(session, list) else []:
            if isinstance(turn, dict):
                text = turn.get('text', '') + turn.get('blip', '')
                if 'mel' in text.lower() and ('kids' in text.lower() or 'children' in text.lower() or 'craft' in text.lower() or 'paint' in text.lower() or 'creative' in text.lower()):
